/**
 * The parameters that protect credentials, and the shape of a resolved identity.
 *
 * These numbers are pinned here rather than in `api` for the reason ARCHITECTURE.md 12.1 gives:
 * they describe a stored artefact. A password hashed with one memory cost has to be verifiable
 * by every later build, and a TOTP code generated by a phone has to be checked with the period
 * the enrolment QR code declared. Both outlive the process that created them, so both belong in
 * the package that both sides of the boundary read.
 */
import { z } from 'zod';

import { permissionKeySchema, permissionScopeSchema, PERMISSION_EFFECTS } from './permissions.js';

/**
 * argon2id parameters.
 *
 * The OWASP minimum for argon2id at the time of writing: 19 MiB of memory, two passes, one lane.
 * Memory is the expensive axis for an attacker with GPUs, which is why it is the one raised
 * first if these are ever tuned. Raising any of them is safe for existing hashes - the encoded
 * string carries the parameters it was made with, so old hashes keep verifying and are rehashed
 * on the next successful sign-in.
 */
export const ARGON2ID_PARAMS = {
  /** Kibibytes of memory per hash. */
  memoryCost: 19_456,

  /** Passes over that memory. */
  timeCost: 2,

  /** Lanes. One, because the API process is already concurrent across requests. */
  parallelism: 1,
} as const;

/**
 * How long an access token is valid, in seconds.
 *
 * Fifteen minutes is the compromise ARCHITECTURE.md 12.1 fixes. A JWT cannot be revoked, so this
 * number is the true upper bound on how long a revoked session, a demoted user or a deleted
 * account keeps working. Shorter would mean refreshing constantly; longer would make revocation
 * a promise the system cannot keep.
 */
export const ACCESS_TOKEN_TTL_SECONDS = 900;

/** How long a refresh token is valid, in seconds. Thirty days. */
export const REFRESH_TOKEN_TTL_SECONDS = 2_592_000;

/** How long a session may live before requiring a fresh sign-in, in seconds. Ninety days. */
export const SESSION_TTL_SECONDS = 7_776_000;

/** How long a pending two-factor challenge stays usable, in seconds. */
export const TWO_FACTOR_CHALLENGE_TTL_SECONDS = 300;

/** The `iss` claim on every access token. */
export const ACCESS_TOKEN_ISSUER = 'nebula-home';

/** The `aud` claim on every access token. */
export const ACCESS_TOKEN_AUDIENCE = 'nebula-home-api';

/** The JWS algorithm access tokens are signed with. */
export const ACCESS_TOKEN_ALGORITHM = 'HS256';

/**
 * The visible prefix on every personal access token.
 *
 * Present so that a token pasted into a chat message or committed to a repository can be
 * recognised by a secret scanner, and so a person reading a list of tokens can tell which
 * string is which.
 */
export const PERSONAL_ACCESS_TOKEN_PREFIX = 'nbh_';

/** Bytes of entropy in a refresh token and in a personal access token. */
export const OPAQUE_TOKEN_BYTES = 32;

/** TOTP parameters, fixed by RFC 6238 defaults so that any authenticator app works. */
export const TOTP_PARAMS = {
  /** Digits in a generated code. */
  digits: 6,

  /** Seconds one code is valid for. */
  periodSeconds: 30,

  /** The HMAC hash. SHA-1 is what every authenticator app implements. */
  algorithm: 'SHA1',

  /**
   * How many periods either side of now are accepted.
   *
   * One, which tolerates roughly thirty seconds of clock drift on the phone. Widening this
   * multiplies the number of codes valid at any moment, which is exactly the thing a
   * time-based code exists to keep small.
   */
  windowSteps: 1,

  /** Bytes in a generated secret. */
  secretBytes: 20,
} as const;

/**
 * What marks a token-claim entry as a denial.
 *
 * An exclamation mark cannot appear in a permission key or a scope - both are constrained to
 * lower-case letters, digits, underscore and dot - so it can never be mistaken for part of one.
 */
export const DENY_PREFIX = '!';

/** How many recovery codes are issued when two-factor authentication is enabled. */
export const TOTP_RECOVERY_CODE_COUNT = 10;

/** How many consecutive failed sign-ins lock an account. */
export const FAILED_LOGIN_LIMIT = 10;

/** How long an account stays locked after {@link FAILED_LOGIN_LIMIT} failures, in seconds. */
export const ACCOUNT_LOCK_SECONDS = 900;

/**
 * A permission and where it applies.
 *
 * The scope is a separate field rather than a third segment of the key, for the reason
 * ARCHITECTURE.md 12.2 gives: one grant row narrows an existing permission to an area, instead
 * of inventing a second permission that means "the same thing, but only here".
 */
export const scopedPermissionSchema = z.object({
  /** `<resource>:<action>`. */
  key: permissionKeySchema,

  /** `*` for everything, or `area.x` / `entity.x` / `label.x`. */
  scope: z.union([z.literal('*'), permissionScopeSchema]),
});

/** A permission and where it applies. */
export type ScopedPermission = z.output<typeof scopedPermissionSchema>;

/**
 * One permission grant.
 *
 * Denials survive resolution rather than being subtracted from the allow set, because they
 * cannot be: "everything except the garage" is not expressible as a list of allows without
 * enumerating every area that exists now and every one added later. A deny is carried and
 * checked, which is also what makes it beat a wider allow.
 */
export const grantedPermissionSchema = scopedPermissionSchema.extend({
  /** Whether this grant allows or denies. */
  effect: z.enum(PERMISSION_EFFECTS),
});

/** One permission grant. */
export type GrantedPermission = z.output<typeof grantedPermissionSchema>;

/** How a request proved who it came from. */
export const CREDENTIAL_KINDS = ['session', 'access_token'] as const;

/** How a request proved who it came from. */
export type CredentialKind = (typeof CREDENTIAL_KINDS)[number];

/**
 * Who a request is from, once its credential has been verified.
 *
 * Assembled once per request and never rebuilt: every authorisation decision in the request
 * reads this same object, so a permission cannot appear to change halfway through handling one
 * call.
 */
export const identitySchema = z.object({
  /** The user the credential belongs to. */
  userId: z.uuid(),

  /** Their username, carried for the audit log so a record survives the user's deletion. */
  username: z.string().min(1).max(64),

  /** The role key they hold. */
  role: z.string().min(1).max(64),

  /** Their role's grants and their own, denials included. */
  permissions: z.array(grantedPermissionSchema),

  /** How they proved it. */
  credential: z.enum(CREDENTIAL_KINDS),

  /** The session, when the credential was a session token rather than a personal one. */
  sessionId: z.uuid().optional(),

  /** The personal access token, when that is what was presented. */
  accessTokenId: z.uuid().optional(),
});

/** Who a request is from, once its credential has been verified. */
export type Identity = z.output<typeof identitySchema>;

/**
 * What an access token carries.
 *
 * The permission set is embedded rather than looked up per request, which is what makes the
 * service stateless. The cost is that a permission change takes effect at the next refresh
 * rather than immediately, bounded by {@link ACCESS_TOKEN_TTL_SECONDS}.
 */
export const accessTokenClaimsSchema = z.object({
  /** The user id. */
  sub: z.uuid(),

  /** The session id, so a refresh can find the family this token belongs to. */
  sid: z.uuid(),

  /** The username at the time the token was issued. */
  usr: z.string().min(1).max(64),

  /** The role key at the time the token was issued. */
  rol: z.string().min(1).max(64),

  /**
   * The resolved grants: each entry is `key`, or `key:scope`, or either of those prefixed with
   * an exclamation mark to mark a denial.
   */
  prm: z.array(z.string().min(3).max(129)),

  /** Issued at, seconds since the epoch. */
  iat: z.int(),

  /** Expires at, seconds since the epoch. */
  exp: z.int(),
});

/** What an access token carries. */
export type AccessTokenClaims = z.output<typeof accessTokenClaimsSchema>;

/**
 * Renders a grant as one string, for the token claim.
 *
 * @param permission - The grant to render.
 * @returns `key` when the scope is everything and `key:scope` otherwise, prefixed with an
 * exclamation mark when the grant is a denial.
 */
export function formatPermission(permission: GrantedPermission): string {
  const body = permission.scope === '*' ? permission.key : `${permission.key}:${permission.scope}`;

  return permission.effect === 'deny' ? `${DENY_PREFIX}${body}` : body;
}

/**
 * Reads a grant back out of a token claim.
 *
 * The key is always exactly two segments (ARCHITECTURE.md 12.2), so anything after the second
 * colon is the scope and nothing else - splitting on every colon would turn `entity:control` at
 * scope `area.living_room` into three meaningless parts.
 *
 * @param value - One entry of the `prm` claim.
 * @returns The grant, or null when the string is not one.
 */
export function parsePermission(value: string): GrantedPermission | null {
  const isDeny = value.startsWith(DENY_PREFIX);
  const body = isDeny ? value.slice(DENY_PREFIX.length) : value;
  const separator = body.indexOf(':', body.indexOf(':') + 1);
  const key = separator === -1 ? body : body.slice(0, separator);
  const scope = separator === -1 ? '*' : body.slice(separator + 1);
  const parsed = grantedPermissionSchema.safeParse({
    key,
    scope,
    effect: isDeny ? 'deny' : 'allow',
  });

  return parsed.success ? parsed.data : null;
}
